CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE SCHEMA IF NOT EXISTS portal;
CREATE TABLE IF NOT EXISTS portal.workspaces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS portal.members (workspace_id uuid NOT NULL REFERENCES portal.workspaces(id), user_id uuid NOT NULL, role text NOT NULL CHECK(role IN ('owner','admin','member')), PRIMARY KEY(workspace_id,user_id));
CREATE TABLE IF NOT EXISTS portal.products (slug text PRIMARY KEY, name text NOT NULL, description text NOT NULL, category text NOT NULL, enabled boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS portal.plans (slug text PRIMARY KEY, name text NOT NULL, monthly_cents integer, description text NOT NULL);
CREATE TABLE IF NOT EXISTS portal.entitlements (plan_slug text REFERENCES portal.plans(slug), feature text NOT NULL, quota integer, PRIMARY KEY(plan_slug,feature));
CREATE TABLE IF NOT EXISTS portal.subscriptions (workspace_id uuid PRIMARY KEY REFERENCES portal.workspaces(id), plan_slug text REFERENCES portal.plans(slug), status text NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS portal.notes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES portal.workspaces(id), author_id uuid NOT NULL, title text NOT NULL, body text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS portal.support_tickets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES portal.workspaces(id), author_id uuid NOT NULL, subject text NOT NULL, details text NOT NULL, status text NOT NULL DEFAULT 'open', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS portal.meeting_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES portal.workspaces(id), external_meeting_id text NOT NULL, title text NOT NULL, summary text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS portal.report_shares (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), report_id uuid NOT NULL REFERENCES portal.meeting_reports(id), workspace_id uuid NOT NULL REFERENCES portal.workspaces(id), recipient_email text NOT NULL, created_by uuid NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS portal.usage_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES portal.workspaces(id), feature text NOT NULL, units integer NOT NULL CHECK(units>0), idempotency_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,feature,idempotency_key));
CREATE TABLE IF NOT EXISTS portal.ai_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES portal.workspaces(id), meeting_id text NOT NULL, kind text NOT NULL, status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS portal.audit_events (id bigserial PRIMARY KEY, workspace_id uuid NOT NULL, actor_id uuid NOT NULL, action text NOT NULL, object_id text, created_at timestamptz NOT NULL DEFAULT now());
INSERT INTO portal.products(slug,name,description,category) VALUES
('meet','Qorlla Meet','Meetings, schedules and collaboration','Collaboration'),('receptionist','AI Receptionist','Automated reception and appointment routing','Communication'),('phone','Qorlla Phone','Business calls and voicemail','Communication'),('notes','My Notes','Private notes and meeting reports','Productivity'),('mate','QorllaMate','AI assistant and workflow approvals','AI'),('suite','AI Productivity Suite','Documents, sheets, slides and workspace files','Productivity') ON CONFLICT(slug) DO NOTHING;
INSERT INTO portal.plans(slug,name,monthly_cents,description) VALUES ('basic','Basic',0,'Free workplace access'),('pro','Pro',1699,'Individual and small team collaboration'),('business','Business',2199,'Advanced team collaboration'),('enterprise','Enterprise',NULL,'Contact sales') ON CONFLICT(slug) DO NOTHING;
